using System;

namespace ZeroGraphics.Imaging.Gpu.Shaders
{
    /// <summary>
    /// Precompiled Direct3D 11 Shader Model 4.0 Bytecodes for the Camera Viewport Pipeline.
    /// Eliminates any runtime shader compiler dependency.
    /// </summary>
    public static class CameraViewportBytecodes
    {
        private static readonly Lazy<byte[]> _vsMain = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        private static readonly Lazy<byte[]> _psR8 = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        private static readonly Lazy<byte[]> _psColor = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        private static readonly Lazy<byte[]> _psFlatColor = new Lazy<byte[]>(() =>
            Convert.FromBase64String(""));

        public static byte[] VsMainBytecode => _vsMain.Value;
        public static byte[] PsR8Bytecode => _psR8.Value;
        public static byte[] PsColorBytecode => _psColor.Value;
        public static byte[] PsFlatColorBytecode => _psFlatColor.Value;
    }
}
